"""Episode-level replay buffer for LBM-Act training."""

from __future__ import annotations

import os
import random
from typing import List

import numpy as np
import torch
from torch.utils.data import Dataset


# Files generated by the AuctionNet preprocessing pipeline. The buffer
# concatenates all matching shards under ``data_path``.
DENSE_TRAJ_FILES = (
    "preprocessed_trajectory_data_0.npy",
    "preprocessed_trajectory_data_1.npy",
    "preprocessed_trajectory_data_2.npy",
)
SPARSE_TRAJ_FILES = (
    "preprocessed_trajectory_data_final_1.npy",
    "preprocessed_trajectory_data_final_2.npy",
    "preprocessed_trajectory_data_final_3.npy",
)

# Padding value for missing actions in shorter-than-K trajectories.
ACTION_PADDING_VALUE = -10.0


def _filter_trajectories(trajectories: List[dict], min_initial_action: float = 2.0) -> List[dict]:
    """Drop short trajectories and trajectories whose first action is too small."""
    return [
        traj
        for traj in trajectories
        if traj["observations"].shape[0] > 2 and traj["actions"][0] > min_initial_action
    ]


class EpisodeReplayBuffer(Dataset):
    """Sliding-window dataset over preprocessed AuctionNet trajectories."""

    def __init__(
        self,
        state_dim: int,
        act_dim: int,
        data_path: str,
        max_ep_len: int = 48,
        scale: float = 2000.0,
        K: int = 4,
        load_preprocessed_data: bool = True,
        sparse_data: bool = False,
        device: str = "cpu",
    ):
        super().__init__()
        self.device = device
        self.max_ep_len = max_ep_len
        self.scale = scale
        self.state_dim = state_dim
        self.act_dim = act_dim
        self.K = K

        print(f"[EpisodeReplayBuffer] reward / RTG normalisation scale: {scale}")

        if load_preprocessed_data:
            files = SPARSE_TRAJ_FILES if sparse_data else DENSE_TRAJ_FILES
            print(f"[EpisodeReplayBuffer] loading {'sparse' if sparse_data else 'dense'} trajectories")
            shards = [
                np.load(os.path.join(data_path, f), allow_pickle=True).tolist()
                for f in files
            ]
            self.trajectories = [t for shard in shards for t in shard]
            self.trajectories = _filter_trajectories(self.trajectories)

            self.traj_lens = np.array([len(t["observations"]) for t in self.trajectories])
            self.returns = np.array([float(np.sum(t["rewards"])) for t in self.trajectories])

            tmp_states = np.concatenate([t["observations"] for t in self.trajectories], axis=0)
            self.state_mean = np.mean(tmp_states, axis=0)
            self.state_std = np.std(tmp_states, axis=0)

        # Use the longest 100% of trajectories ranked by return.
        self.pct_traj = 1.0
        num_timesteps = max(int(self.pct_traj * np.sum(self.traj_lens)), 1)
        sorted_inds = np.argsort(self.returns)
        timesteps = self.traj_lens[sorted_inds[-1]]
        num_trajectories = 1
        ind = len(self.trajectories) - 2
        while ind >= 0 and timesteps + self.traj_lens[sorted_inds[ind]] <= num_timesteps:
            timesteps += self.traj_lens[sorted_inds[ind]]
            num_trajectories += 1
            ind -= 1
        self.sorted_inds = sorted_inds[-num_trajectories:]
        self.p_sample = self.traj_lens[self.sorted_inds] / float(np.sum(self.traj_lens[self.sorted_inds]))

    # ------------------------------------------------------------------ #
    @staticmethod
    def discount_cumsum(x: np.ndarray, gamma: float = 1.0) -> np.ndarray:
        out = np.zeros_like(x)
        out[-1] = x[-1]
        for t in reversed(range(x.shape[0] - 1)):
            out[t] = x[t] + gamma * out[t + 1]
        return out

    def __len__(self) -> int:
        return len(self.sorted_inds)

    def __getitem__(self, index: int):
        traj = self.trajectories[int(self.sorted_inds[index])]
        K = self.K
        start_t = random.randint(0, traj["rewards"].shape[0] - 1)

        s = traj["observations"][start_t : start_t + K]
        a = traj["actions"][start_t : start_t + K]
        r = traj["rewards"][start_t : start_t + K].reshape(-1, 1)
        c = traj["cost_ts"][start_t : start_t + K].reshape(-1, 1)
        d = traj.get("terminals", traj.get("dones"))[start_t : start_t + K]

        timesteps = np.arange(start_t, start_t + s.shape[0])
        timesteps[timesteps >= self.max_ep_len] = self.max_ep_len - 1

        rtg = self.discount_cumsum(traj["rewards"][start_t:], gamma=1.0)[: s.shape[0] + 1].reshape(-1, 1)
        if rtg.shape[0] <= s.shape[0]:
            rtg = np.concatenate([rtg, np.zeros((1, 1))], axis=0)

        tlen = s.shape[0]
        pad = K - tlen
        s = np.concatenate([np.zeros((pad, self.state_dim)), s], axis=0)
        if self.scale != 1:
            s = (s - self.state_mean) / self.state_std
        a = np.concatenate([np.ones((pad, self.act_dim)) * ACTION_PADDING_VALUE, a], axis=0)
        r = np.concatenate([np.zeros((pad, 1)), r], axis=0) / self.scale
        c = np.concatenate([np.zeros((pad, 1)), c], axis=0) / traj["budget"]
        d = np.concatenate([np.ones((pad,)) * 2, d], axis=0)
        rtg = np.concatenate([np.zeros((pad, 1)), rtg], axis=0) / self.scale
        timesteps = np.concatenate([np.zeros((pad,)), timesteps], axis=0)
        mask = np.concatenate([np.zeros((pad,)), np.ones((tlen,))], axis=0)

        to_t = lambda x, dt: torch.from_numpy(x).to(dtype=dt, device=self.device)
        return (
            to_t(s, torch.float32),
            to_t(a, torch.float32),
            to_t(r, torch.float32),
            to_t(d, torch.long),
            to_t(rtg, torch.float32),
            to_t(timesteps, torch.long),
            torch.from_numpy(mask).to(device=self.device),
            traj["budget"],
            traj["cpa_constrain"],
            to_t(c, torch.float32),
        )
